SQL_DOC.P_SQL:
SELECT '01' AS COMLTD , 'D4240' AS VSRNO , SO03.SHPDSTN_SRLNO||replace(SV02.DEAL_STTMN_NO,sv01.cstmr_id,'') AS SLNO , SUBSTR(SO06.IF_ORDR_NO,1,8) AS SRNO , SUBSTR(SO06.IF_ORDR_SEQ,9,2) AS SRNO1 , SUBSTR(SO03.SHPDSTN_SRLNO ,1,1) AS XPLANT , SUBSTR(SO03.SHPDSTN_SRLNO,2,1) AS DIV , SO06.GDS_CD AS ITNO , nvl(trim(IFPO.DESCRIPTION),'.') AS ITNM , nvl(trim(IFPO.SPECIFICATION),'.') AS SPEC , nvl(GETMNFATREINFO(SO04.MNFATRE_CD,'MNFATRE_NM'),' ') AS MAKER , SO04.UNIT_CD AS XUNIT , F_SPLIT(SO04.IF_DEAL_STTMN_DTAIL,'^',5) AS CLS , F_SPLIT(SO04.IF_DEAL_STTMN_DTAIL,'^',6) AS XTYPE , ' ' AS GUBUN , SO04.MNG_NO AS RQNO , SO03.RELIER_ID AS EMPNO , F_SPLIT(SO04.IF_DEAL_STTMN_DTAIL,'^',3) AS DEPT , SV01.DLVRY_DATE AS STDT , TO_CHAR(SV02.FRST_REGST_DATM,'YYYYMMDD') AS PRTDT , SO06.ORDR_QTY AS PQTY , SO06.SLS_UNTPRC AS XCOST , SO06.IF_ORDR_NO AS PURNO , SO04.SHP_HP_DATE AS PDUDT , SV02.DLVRY_QTY AS AQTY , ' ' AS STCD , 'N' AS IFFLAG , DECODE(SV02.USE_CHK,'N','D','C') AS CDFLAG FROM KEPCON.KEPMPSV01 SV01, KEPCON.KEPMPSV02 SV02, KEPCON.KEPMPSO06 SO06, KEPCON.KEPMPSO04 SO04, KEPCON.KEPMPSO03 SO03, KEPCON.IF_PODT IFPO WHERE SV01.CSTMR_ID = 'KRKDAC0001C001' AND SV01.DEAL_STTMN_NO = '$G_RS.DEAL_STTMN_NO$' AND SV01.DEAL_STTMN_NO = SV02.DEAL_STTMN_NO AND SV02.ORDR_NO = SO06.ORDR_NO AND SV02.ORDR_SEQ= SO06.ORDR_SEQ AND SO06.ORDR_RE_NO = SO04.ORDR_RE_NO AND SO06.ORDR_RE_SEQ= SO04.ORDR_RE_SEQ AND SO04.ORDR_RE_NO = SO03.ORDR_RE_NO AND SO06.CSTMR_ID = IFPO.BUYER AND SO06.IF_ORDR_NO = IFPO.LEGACY_PO_NO AND SO06.IF_ORDR_SEQ= IFPO.LEGACY_PO_SEQ
declare begin UPDATE KEPCON.KEPMPSV02 SET SND_CHK = 'Y' ,SND_DATM = SYSDATE WHERE DEAL_STTMN_NO = '$G_RS.DEAL_STTMN_NO$' AND SND_CHK = 'N'; UPDATE KEPCON.KEPMPSV01 SET SND_CHK = 'Y' ,SND_DATM = SYSDATE WHERE DEAL_STTMN_NO = '$G_RS.DEAL_STTMN_NO$' AND SND_CHK = 'N'; end;
UPDATE KEPCON.KEPMPSV01 SET SND_CHK = 'E' , SND_DATM = SYSDATE WHERE DEAL_STTMN_NO = '$G_RS.DEAL_STTMN_NO$' AND SND_CHK = 'N'
